BEGIN;

DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS users;

CREATE TABLE users (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    email VARCHAR(254) NOT NULL UNIQUE,
    password_hash VARCHAR(60),
    google_id VARCHAR(255),
    avatar_url TEXT,
    role VARCHAR(10) NOT NULL DEFAULT 'client' CHECK (role IN ('client', 'admin')),
    phone VARCHAR(30),
    address TEXT,
    city VARCHAR(100),
    region VARCHAR(100),
    is_verified BOOLEAN NOT NULL DEFAULT FALSE,
    verification_token VARCHAR(255),
    verification_expires_at TIMESTAMPTZ,
    reset_password_token VARCHAR(255),
    reset_password_expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE categories (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug VARCHAR(80) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL,
    logo_url TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE products (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(80) NOT NULL UNIQUE,
    category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    price INTEGER NOT NULL CHECK (price >= 0),
    stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),
    game VARCHAR(100) NOT NULL,
    edition VARCHAR(150) NOT NULL,
    rarity VARCHAR(20) NOT NULL CHECK (rarity IN ('Common', 'Uncommon', 'Rare', 'Ultra Rare')),
    color VARCHAR(80) NOT NULL,
    cost INTEGER NOT NULL DEFAULT 0 CHECK (cost >= 0),
    card_type VARCHAR(80) NOT NULL,
    condition VARCHAR(30) NOT NULL CHECK (condition IN ('Near Mint', 'Lightly Played', 'Moderately Played')),
    image_url TEXT NOT NULL,
    has_button BOOLEAN NOT NULL DEFAULT true,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE orders (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_number VARCHAR(40) NOT NULL UNIQUE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    status VARCHAR(20) NOT NULL DEFAULT 'Pendiente' CHECK (status IN ('Pendiente', 'Pagado', 'Enviado', 'Entregado', 'Cancelado', 'Reembolsado')),
    admin_notes TEXT,
    subtotal INTEGER NOT NULL CHECK (subtotal >= 0),
    shipping_cost INTEGER NOT NULL DEFAULT 0 CHECK (shipping_cost >= 0),
    total INTEGER NOT NULL CHECK (total >= 0 AND total = subtotal + shipping_cost),
    shipping_name VARCHAR(150) NOT NULL,
    shipping_email VARCHAR(254) NOT NULL,
    shipping_address TEXT NOT NULL,
    shipping_city VARCHAR(100) NOT NULL,
    shipping_region VARCHAR(100) NOT NULL,
    payment_method VARCHAR(50) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE order_items (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
    product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    unit_price INTEGER NOT NULL CHECK (unit_price >= 0)
);

-- Las claves UNIQUE ya tienen indice; estos cubren relaciones y filtros.
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_products_active_price ON products(is_active, price);
CREATE INDEX idx_products_game ON products(game);
CREATE INDEX idx_products_edition ON products(edition);
CREATE INDEX idx_products_rarity ON products(rarity);
CREATE INDEX idx_products_color ON products(color);
CREATE INDEX idx_products_cost ON products(cost);
CREATE INDEX idx_products_card_type ON products(card_type);
CREATE INDEX idx_products_condition ON products(condition);
CREATE INDEX idx_orders_user ON orders(user_id);
CREATE INDEX idx_orders_status_created ON orders(status, created_at);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_order_items_product ON order_items(product_id);

-- Cuentas de prueba: bcrypt de 10 rondas; reemplazarlas antes de produccion.


-- Catalogo original: codigos, titulos, precios CLP, imagenes, rareza y condicion conservados.
-- Stock de demostracion: 20 unidades; preventas sin stock.
-- Edicion/color desconocidos: Sin especificar; coste 0 hasta contar con ficha tecnica.

-- Pedidos de demostracion; importes calculados desde sus lineas.
SELECT 'TCG-2026-0001', id, 'Pendiente', 23000, 3500, 26500, 'Cliente Demo', 'cliente@tcgstore.com', 'Av. Demo 200', 'Santiago', 'Metropolitana', 'Transferencia' FROM users WHERE email = 'cliente@tcgstore.com';
SELECT o.id, p.id, 1, p.price FROM orders o CROSS JOIN products p WHERE o.order_number = 'TCG-2026-0001' AND p.code = 'accesorios-0';

SELECT 'TCG-2026-0002', id, 'Pagado', 122000, 3500, 125500, 'Cliente Demo', 'cliente@tcgstore.com', 'Av. Demo 200', 'Santiago', 'Metropolitana', 'Transferencia' FROM users WHERE email = 'cliente@tcgstore.com';
SELECT o.id, p.id, 2, p.price FROM orders o CROSS JOIN products p WHERE o.order_number = 'TCG-2026-0002' AND p.code = 'one-piece-14';

SELECT 'TCG-2026-0003', id, 'Enviado', 67000, 3500, 70500, 'Cliente Demo', 'cliente@tcgstore.com', 'Av. Demo 200', 'Santiago', 'Metropolitana', 'Transferencia' FROM users WHERE email = 'cliente@tcgstore.com';
SELECT o.id, p.id, 1, p.price FROM orders o CROSS JOIN products p WHERE o.order_number = 'TCG-2026-0003' AND p.code = 'pokemon-0';

SELECT 'TCG-2026-0004', id, 'Entregado', 12000, 3500, 15500, 'Cliente Demo', 'cliente@tcgstore.com', 'Av. Demo 200', 'Santiago', 'Metropolitana', 'Transferencia' FROM users WHERE email = 'cliente@tcgstore.com';
SELECT o.id, p.id, 1, p.price FROM orders o CROSS JOIN products p WHERE o.order_number = 'TCG-2026-0004' AND p.code = 'riftbound-5';

COMMIT;
